// Firebase configuration for ProBridge website
// Project: app-development-4ee75
import { initializeApp } from 'firebase/app';
import { getAuth } from 'firebase/auth';

const firebaseConfig = {
  apiKey: process.env.REACT_APP_FIREBASE_API_KEY || 'AIzaSyDdxLzeCdznxhX_2sFB7PXTQYEP-fG20k8',
  authDomain: process.env.REACT_APP_FIREBASE_AUTH_DOMAIN || 'app-development-4ee75.firebaseapp.com',
  projectId: process.env.REACT_APP_FIREBASE_PROJECT_ID || 'app-development-4ee75',
  messagingSenderId: process.env.REACT_APP_FIREBASE_MESSAGING_SENDER_ID || '71277334527',
  appId: process.env.REACT_APP_FIREBASE_APP_ID || '1:71277334527:web:probridge',
};

const app = initializeApp(firebaseConfig);
export const auth = getAuth(app);
export default app;
